create extension if not exists pgcrypto with schema extensions;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$$;

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text not null check (char_length(trim(full_name)) > 0),
  role text not null default 'viewer' check (role in ('admin', 'operator', 'viewer')),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table if not exists public.sensors (
  id bigint generated by default as identity primary key,
  sensor_name text not null,
  bedengan text not null,
  location text,
  status text not null default 'Active' check (status in ('Active', 'Inactive', 'Maintenance', 'Offline')),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  constraint sensors_sensor_name_key unique (sensor_name),
  constraint sensors_bedengan_sensor_name_key unique (bedengan, sensor_name)
);

create table if not exists public.sensor_readings (
  id bigint generated by default as identity primary key,
  sensor_id bigint not null references public.sensors (id) on delete cascade,
  moisture numeric(5,2) not null check (moisture >= 0 and moisture <= 100),
  temperature numeric(5,2) check (temperature is null or (temperature >= -50 and temperature <= 100)),
  humidity numeric(5,2) check (humidity is null or (humidity >= 0 and humidity <= 100)),
  pump_status text,
  created_at timestamptz not null default timezone('utc', now()),
  status text generated always as (
    case
      when moisture < 40 then 'Low'
      when moisture > 70 then 'High'
      else 'Normal'
    end
  ) stored
);

create index if not exists sensors_status_idx
  on public.sensors (status);

create index if not exists sensor_readings_sensor_created_at_idx
  on public.sensor_readings (sensor_id, created_at desc);

create index if not exists sensor_readings_created_at_idx
  on public.sensor_readings (created_at desc);

drop trigger if exists set_profiles_updated_at on public.profiles;
create trigger set_profiles_updated_at
before update on public.profiles
for each row
execute function public.set_updated_at();

drop trigger if exists set_sensors_updated_at on public.sensors;
create trigger set_sensors_updated_at
before update on public.sensors
for each row
execute function public.set_updated_at();

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, full_name)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.email, 'User')
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
after insert on auth.users
for each row
execute function public.handle_new_user();

create or replace view public.sensor_logs as
select
  sr.id,
  sr.sensor_id,
  sr.moisture,
  sr.temperature,
  sr.humidity,
  sr.status,
  sr.pump_status as pump,
  sr.created_at
from public.sensor_readings sr;

alter table public.profiles enable row level security;
alter table public.sensors enable row level security;
alter table public.sensor_readings enable row level security;

drop policy if exists "profiles_select_own" on public.profiles;
create policy "profiles_select_own"
on public.profiles
for select
to authenticated
using (auth.uid() = id);

drop policy if exists "profiles_insert_own" on public.profiles;
create policy "profiles_insert_own"
on public.profiles
for insert
to authenticated
with check (auth.uid() = id);

drop policy if exists "profiles_update_own" on public.profiles;
create policy "profiles_update_own"
on public.profiles
for update
to authenticated
using (auth.uid() = id)
with check (auth.uid() = id);

drop policy if exists "sensors_read_all" on public.sensors;
create policy "sensors_read_all"
on public.sensors
for select
to anon, authenticated
using (true);

drop policy if exists "sensor_readings_read_all" on public.sensor_readings;
create policy "sensor_readings_read_all"
on public.sensor_readings
for select
to anon, authenticated
using (true);
